import { access } from 'node:fs/promises'
import path from 'node:path'

/** Dots, purple to magenta, radial. Generated by scripts/project-qrs.sh. */
export function projectQrSrc(slug: string) {
  return `/brand/qr/${slug}.png`
}

export function projectQrAlt(slug: string) {
  return `QR code for ${slug}. Scanning it opens https://pesty.sh/projects/${slug}`
}

export async function projectQr(slug: string) {
  try {
    await access(path.join(process.cwd(), 'public', 'brand', 'qr', `${slug}.png`))
  } catch {
    return null
  }
  return { src: projectQrSrc(slug), alt: projectQrAlt(slug) }
}
